def quarter_of(d):
    y, m, _ = d.split("-")
    return f"{y}-Q{(int(m) - 1) // 3 + 1}"


def month_key(d):
    return d[:7]


for d in ["2025-01-31", "2025-03-01", "2025-04-01", "2025-12-31"]:
    print(f"quarter_of({d!r}) -> {quarter_of(d)!r}")
print(f"month_key('2025-06-30') -> {month_key('2025-06-30')!r}")
print(f"quarter_of('2025-6-30') -> {quarter_of('2025-6-30')!r}")
